INSERT OR IGNORE INTO pages (slug, title, content, sort_order) VALUES ('about-us', 'हमारे बारे में', '<p>NewsPort Express एक हिंदी समाचार पोर्टल है। यहां अपनी संस्था, संपादकीय टीम और उद्देश्य के बारे में लिखें।</p>', 10);
INSERT OR IGNORE INTO pages (slug, title, content, sort_order) VALUES ('contact-us', 'संपर्क करें', '<p>संपादकीय टीम, विज्ञापन और शिकायतों के लिए अपना ईमेल, फोन और पता यहां लिखें।</p>', 20);
INSERT OR IGNORE INTO pages (slug, title, content, sort_order) VALUES ('editorial-policy', 'संपादकीय नीति', '<p>खबरों की पुष्टि, सुधार (करेक्शन) और निष्पक्षता से जुड़ी अपनी नीति यहां लिखें।</p>', 30);
INSERT OR IGNORE INTO pages (slug, title, content, sort_order) VALUES ('privacy-policy', 'प्राइवेसी पॉलिसी', '<p>आप कौन-सा डेटा इकट्ठा करते हैं और उसका उपयोग कैसे करते हैं, यहां लिखें।</p>', 40);
INSERT OR IGNORE INTO pages (slug, title, content, sort_order) VALUES ('terms', 'नियम और शर्तें', '<p>वेबसाइट के उपयोग की शर्तें यहां लिखें।</p>', 50);
INSERT OR IGNORE INTO pages (slug, title, content, sort_order) VALUES ('advertise', 'विज्ञापन दें', '<p>विज्ञापन के लिए संपर्क जानकारी यहां लिखें।</p>', 60);
